"""Hard rules that keep a case from scoring 0 by mistake. Code, not judgement; checked before every
send and every accept, whatever the strategy decided.

Accept:  the sheet is the supplier's current standing offer; it keeps every must-have on the terms
         it would really close on (sheet, then the supplier's standard terms from its quote PDF) -
         and a must-have field we cannot read from either counts as broken; C is finite and beats
         the alternative - and, when there is one, the cheapest opening too (else the alternative
         scores at least as much).
Send:    every term sheet carries exactly the negotiable fields with allowed values and keeps the
         must-haves (a supplier may agree to any sheet we send, and we must be able to accept it);
         every cited ID exists in the data, the case's facts or this session's offers - a sentence
         whose IDs are all unknown goes, and so does a threat or an "other offer" without a rival's
         offer cited (conduct.py); at most 3 sheets and 20 refs.
"""

import math
import re

from arena_kit.cost import must_haves_ok

from negotiator.conduct import unsupported_sentences

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")
MAX_SHEETS = 3
MAX_REFS = 20


def unreadable_must_have_fields(case: dict, terms: dict, standard: dict | None) -> list[str]:
    """Must-have fields neither the sheet, the supplier's standard terms nor the case fixes.

    `closing_terms` fills such gaps from the buyer's plan (e.g. lead time = what we need), which
    would let a sheet pass that the arena closes on the supplier's real standard - unknown to us."""
    known = {**(standard or {}), **case.get("fixed_terms", {}), **{k: v for k, v in terms.items() if v is not None}}
    return [m["field"] for m in case["buyer"].get("must_haves", []) if m["field"] not in known]


def accept_problems(neg, supplier_id: str, term_sheet_id: str | None) -> list[str]:
    """Why accepting this sheet would be a mistake (empty: safe)."""
    t = neg.threads.get(supplier_id)
    if t is None:
        return ["unknown supplier"]
    standing_id, terms = t.standing
    problems = []
    if not term_sheet_id or term_sheet_id != standing_id:
        # the arena closes on the primary sheet whatever id we send (P10): only that one can be accepted
        problems.append(f"{term_sheet_id} is not the standing offer {standing_id}")
    if not terms or terms.get("unit_price") is None:
        problems.append("the standing offer has no price")
        return problems
    std = t.standard_terms
    if missing := unreadable_must_have_fields(neg.case, terms, std):
        problems.append(f"must-have field(s) {missing} unknown: no quote PDF standard terms")
    if not must_haves_ok(neg.case, terms, std):
        problems.append("breaks a must-have")
    c = neg.cost(supplier_id, terms)
    if not math.isfinite(c):
        problems.append("C is not finite")
    elif c >= neg.c_alt:
        problems.append(f"C {c:,.0f} does not beat the alternative {neg.c_alt:,.0f}")
    elif math.isfinite(neg.c_alt) and c >= neg.c_open:
        # a deal no better than the cheapest opening scores 0; the alternative scores at least that
        problems.append(f"C {c:,.0f} is not better than the opening {neg.c_open:,.0f}")
    return problems


def sheet_problems(case: dict, terms: dict, standard: dict | None = None) -> list[str]:
    problems = []
    negotiable = case["negotiable"]
    if set(terms) != set(negotiable):
        problems.append(f"fields {sorted(terms)} != negotiable {sorted(negotiable)}")
    options = case.get("term_options", {})
    for f, v in terms.items():
        if f == "unit_price":
            if not isinstance(v, int | float) or v <= 0:
                problems.append(f"unit_price {v!r}")
        elif options.get(f) and v not in options[f]:
            problems.append(f"{f}={v!r} not in options")
    # on the terms it would close on: a must-have on a field that is neither negotiable nor fixed is kept
    # (or broken) by the supplier's standard terms, not by our sheet
    if not must_haves_ok(case, terms, standard):
        problems.append("breaks a must-have")
    return problems


def known_id(neg, ref: str) -> bool:
    if neg.data and neg.data.fact(ref):
        return True
    if ref in (neg.case.get("facts") or {}):
        return True
    return any(
        s.get("term_sheet_id") == ref
        for t in neg.threads.values()
        for m in t.supplier_messages
        for s in m.get("term_sheets") or []
    )


def clean_message(neg, supplier_id: str, message: dict) -> tuple[dict, list[str]]:
    """The message with invalid sheets and unknown IDs removed, and what was removed."""
    removed: list[str] = []
    sheets = []
    for sheet in (message.get("term_sheets") or [])[:MAX_SHEETS]:
        thread = neg.threads.get(supplier_id)
        problems = sheet_problems(neg.case, sheet.get("terms", {}), thread.standard_terms if thread else None)
        if problems:
            removed.append(f"sheet {sheet.get('terms')}: {'; '.join(problems)}")
        elif sheet not in sheets:
            sheets.append(sheet)
    refs = []
    for ref in message.get("refs") or []:
        if known_id(neg, ref):
            if ref not in refs:
                refs.append(ref)
        else:
            removed.append(f"ref {ref}")

    def keep(m: re.Match) -> str:
        if known_id(neg, m.group(0)):
            return m.group(0)
        removed.append(f"body id {m.group(0)}")
        return ""

    # conduct.py: no claim without its source, no threat or "other offer" we cannot show
    rival_ids = {
        s.get("term_sheet_id")
        for other, t in neg.threads.items()
        if other != supplier_id
        for m in t.supplier_messages
        for s in m.get("term_sheets") or []
    }
    rival_cited = any(r in rival_ids or r.startswith("quote:") for r in refs)
    body, unsupported = unsupported_sentences(message.get("body") or "", ID_RE, lambda i: known_id(neg, i), rival_cited)
    removed += [f"unsupported sentence: {s}" for s in unsupported]
    body = ID_RE.sub(keep, body)
    body = re.sub(r"\s*\(\s*[,;\s]*\)", "", body)
    out = {**message, "body": body[:8000], "subject": (message.get("subject") or "")[:300], "refs": refs[:MAX_REFS]}
    if "term_sheets" in message:
        out["term_sheets"] = sheets
    return out, removed

"""The full menu: every combination of the case's term options, priced to cost us the same C.

At equal C the structures differ only in what they give the supplier, so we can pick by acceptance:
  - the supplier's explicit requests, read from its e-mails ("which volume can you commit to?",
    "we cannot accept a fixed price for extended contract durations" -> an index clause);
  - closeness to the structure it proposed itself (it tells us what it likes by what it offers);
  - the price it gets (at equal C, the structure that costs us least leaves it the highest price).
Cases have 20-60 combinations, a few hundred at most: all of them fit easily in the time per move.
"""

import itertools
import re

from arena_kit.cost import complete_offer

MAX_COMBOS = 3000

# what a supplier asks for in its own words -> the lever that answers it
REQUESTS = {
    "index_clause": re.compile(
        r"index clause|price adjustment clause|surcharge clause|cannot accept a fixed price|fixed price for "
        r"(?:extended|longer)|material (?:price )?(?:risk|volatil)|costs? remain volatile|alloy surcharge",
        re.I,
    ),
    "contract_months": re.compile(
        r"longer[- ]term|long-term|multi-year|\b(?:24|36)[- ]month|extended contract|longer contract|contract "
        r"duration|firm, long",
        re.I,
    ),
    "volume_per_year": re.compile(
        r"volume commitment|commit to (?:a )?(?:higher )?volume|which volume|binding (?:higher )?volume|higher volume",
        re.I,
    ),
    "ppm_commitment": re.compile(r"quality commitment|\bppm\b|defect rate", re.I),
    "chargeback_eur_per_complaint": re.compile(r"chargeback|per complaint", re.I),
    "lead_time_days": re.compile(r"lead ?time|lieferzeit|deliver in", re.I),
    "incoterm": re.compile(r"incoterm|\b(?:EXW|FCA|DAP)\b|freight", re.I),
    "effective_date": re.compile(r"effective (?:date|from)|valid from|starting (?:on|from)|start(?:ing)? date", re.I),
    "tooling_eur": re.compile(r"tooling", re.I),
    "payment_days": re.compile(
        r"faster payment|pay(?:ing)? (?:us )?earlier|earlier payment|payment within|shorter payment|cash ?flow|"
        r"pay our invoices",
        re.I,
    ),
}


def requests_in(text: str) -> set[str]:
    return {lever for lever, pattern in REQUESTS.items() if pattern.search(text or "")}


def combos(case: dict) -> list[dict]:
    """Every combination of the negotiable non-price fields' options (capped)."""
    options = case.get("term_options", {})
    fields = [f for f in case["negotiable"] if f != "unit_price" and options.get(f)]
    values = [options[f] for f in fields]
    out = []
    for combo in itertools.product(*values):
        out.append(dict(zip(fields, combo, strict=True)))
        if len(out) >= MAX_COMBOS:
            break
    return out or [{}]


def proposed_values(case: dict, sheets: list[dict]) -> dict[str, list]:
    """The values the supplier itself put on its sheets (its offer and its alternatives), per negotiable field:
    what it names is what it is willing to trade on."""
    out: dict[str, list] = {}
    for sheet in sheets:
        for f, v in (sheet.get("terms") or {}).items():
            if f != "unit_price" and f in case["negotiable"] and v not in out.setdefault(f, []):
                out[f].append(v)
    return out


def satisfies(case: dict, terms: dict, theirs: dict, lever: str, proposed: dict | None = None) -> bool:
    """Does this structure answer the supplier's request for `lever`? Only negotiable fields count; where the
    supplier named values itself, meeting one of them answers it."""
    if lever not in case["negotiable"]:
        return False
    if proposed and proposed.get(lever) and lever not in ("index_clause",):
        return terms.get(lever) in proposed[lever]
    if lever == "index_clause":
        return terms.get("index_clause") is not None
    if lever == "payment_days":
        return terms.get("payment_days", 999) <= theirs.get("payment_days", 999)
    if lever in ("contract_months", "volume_per_year"):
        options = [o for o in case.get("term_options", {}).get(lever, []) if o is not None]
        floor = max(theirs.get(lever) or 0, min(options) if options else 0)
        return (terms.get(lever) or 0) >= floor and (terms.get(lever) or 0) > (min(options) if options else 0)
    return lever in theirs and terms.get(lever) == theirs.get(lever)  # its own value on that lever


def acceptance(case: dict, terms: dict, theirs: dict, requests: set[str], proposed: dict | None = None) -> tuple:
    """How readily the supplier takes this structure: requests answered, then likeness to its own."""
    answered = sum(satisfies(case, terms, theirs, r, proposed) for r in requests)
    alike = sum(1 for f, v in terms.items() if f != "unit_price" and theirs.get(f) == v)
    return answered, alike


def structure_key(terms: dict) -> str:
    return repr(sorted((k, v) for k, v in terms.items() if k != "unit_price"))


def priced_menu(case: dict, theirs: dict, price_for) -> list[dict]:
    """Every structure, completed and priced by `price_for(terms) -> price` (e.g. iso-C to our ask)."""
    out = []
    for combo in combos(case):
        terms = complete_offer(case, {**theirs, **combo})
        price = price_for(terms)
        if price and price > 0:
            out.append(complete_offer(case, {**terms, "unit_price": round(price, 2)}))
    return out

            # little and it a lot; P02's paid early instead of a price its margin could not carry
            answered, alike = acceptance(case, t, theirs, plan.requests, plan.proposed)
            worth = plan.belief.value(t) if asymmetric else 0.0
            return (answered, round(worth, 4), alike, t["unit_price"])

        # what a package is worth to it ranks the options only where the data shows a lever is worth much more to
        # it than it costs us: chargebacks at its real defect rate (scorecard). On payment days and freight both
        # sides value money alike - offering it the cash-richest package (D02: 14 days, EXW) only bought it a
        # structure that is dear for us, not a lower price (sandbox 0.608 -> 0.535)
        asymmetric = bool(plan.belief and plan.belief.ppm and "chargeback_eur_per_complaint" in case["negotiable"])

        for t in pool:  # a structure offered before never comes back at a lower price
            before = plan.offered.get(structure_key(t))
            if before is not None and t["unit_price"] < before:
                t["unit_price"] = before
        pool = [t for t in pool if neg.cost(sid, t) < their_c] or pool
        top = max(t["unit_price"] for t in pool)
        pool = [t for t in pool if t["unit_price"] >= top * (1 - MAX_SPREAD)]
        picked = [max(pool, key=lambda t: t["unit_price"]), max(pool, key=rank)]
        if plan.lever_turn:  # a structure it has not seen yet carries our step
            new = [t for t in pool if structure_key(t) not in plan.offered]
            if new:
                picked[1] = max(new, key=rank)
            plan.lever_turn = False
        lead, before = picked[0], plan.offered.get(structure_key(picked[0]))
        if before is not None and lead["unit_price"] <= before:  # "your proposal remains unchanged"
            bumped = round(before * (1 + MIN_STEP), 2)
            if bumped < theirs.get("unit_price", bumped + 1):
                lead["unit_price"] = bumped
        seen = {structure_key(t) for t in picked}
        for t in sorted(pool, key=rank, reverse=True):
            if structure_key(t) not in seen:
                picked.append(t)
                break
        for t in picked:
            before = plan.offered.get(structure_key(t))
            if before is not None and t["unit_price"] <= before:
                bumped = round(before * (1 + MIN_STEP), 2)
                if bumped < theirs.get("unit_price", bumped + 1):
                    t["unit_price"] = bumped
        out, keys = [], set()
        for t in picked:
            if structure_key(t) not in keys:
                keys.add(structure_key(t))
                out.append({"terms": t})
                plan.offered[structure_key(t)] = max(plan.offered.get(structure_key(t), 0.0), t["unit_price"])
        return out[:3]

    def _trade_terms(self, neg, sid, plan, ideal: dict) -> dict | None:
        """Our terms with the levers the supplier values given to it (the price pays for them)."""
        options = neg.case.get("term_options", {})
        negotiable = neg.case["negotiable"]
        trade = dict(ideal)
        changed = False
        for f in plan.policy.trade_first or ("payment_days",):
            if f not in negotiable or not options.get(f):
                continue
            values = [v for v in options[f] if v is not None]
            if not values:
                continue
            if f == "payment_days":
                pick = min(values)  # early payment: cash for the supplier
            elif f == "contract_months":
                pick = max(values)  # security; beyond our horizon it costs us nothing
            elif f == "volume_per_year":
                need = neg.buyer.get("need_per_year", 0)
                fitting = [v for v in values if v <= need] or values
                pick = max(fitting)
            else:
                continue
            if trade.get(f) != pick and neg.keeps_must_haves(sid, {**trade, f: pick}):
                trade[f] = pick
                changed = True
        return trade if changed else None

    # ------------------------------------------------------------------ arguments and words
    def _choose_claims(self, neg, sid, plan, first: bool) -> list[Evidence]:
        banned = plan.banned_kinds | self.banned_case_kinds
        if neg.buyer.get("category_goal") != "quality_first":
            banned = banned | {"scorecard"}
        fresh = [e for e in plan.counters if e.kind not in banned and e.sentence not in plan.used_sentences]
        fresh.sort(key=lambda e: -e.strength)
        pool = fresh + [e for e in plan.evidence if e.kind not in banned and e.sentence not in plan.used_sentences]
        rival = self._rival_evidence(neg, sid)
        if rival and "rival_offer" not in banned:
            pool.insert(0, rival)
        prefer: list[str] = []
        for key in [*sorted(plan.profile.traits), neg.buyer.get("category_goal", "")]:
            prefer += EVIDENCE_FIRST.get(key, [])
        pool.sort(key=lambda e: (e not in fresh, e.kind not in prefer, -e.strength))
        picked, kinds = [], set()
        limit = plan.policy.claims_first if first else (2 if fresh else 1)
        for e in pool:
            if len(picked) >= limit:
                break
            if e.kind == "rival_offer":
                if any((sid, r) in self.used_rival_refs for r in e.refs):
                    continue
            elif any(r in self.used_refs for r in e.refs) or (e.kind in kinds and e.kind != "recent_drop"):
                continue
            series = (e.meta or {}).get("series")
            if self.flags["dedupe_series"] and series and series in self.used_series:
                continue
            picked.append(e)
            kinds.add(e.kind)
            plan.used_sentences.add(e.sentence)
            if series:
                self.used_series.add(series)
        for e in picked:
            if e.kind == "rival_offer":
                self.used_rival_refs.update((sid, r) for r in e.refs)
            else:
                self.used_refs.update(e.refs)
        return picked

    def _write(self, neg, plan: Plan, sheets: list[dict], claims: list[Evidence], probe: bool) -> dict:
        p, case = plan.profile, neg.case
        first = neg.threads[plan.supplier_id].rounds_used == 0
        lines = [f"Dear {plan.name} team,", ""]
        if first:
            if p.has("relationship") or neg.buyer.get("category_goal") in RELATIONSHIP_GOALS:
                lines.append("thank you for your quote and for the reliable cooperation we value.")
            else:
                lines.append("thank you for your quote. We have reviewed it carefully against our data.")
        elif probe:
            lines.append("thank you - we are close. One last step from your side and we can sign.")
        elif plan.stalls:
            pressure = (
                f"{plan.pressures[-1]} weighs on your costs" if plan.pressures else "your costs are under pressure"
            )
            lines.append(
                f"thank you for your reply. We understand that {pressure}; to meet you, we propose a different "
                "structure."
            )
        else:
            lines.append("thank you for your reply and the step towards us. We move as well.")
        lines += [c.sentence for c in claims]
        if not plan.asked_breakdown and p.has("open_book") and not plan.breakdown_read:
            lines.append("Could you send us a cost breakdown for this part?")
            plan.asked_breakdown = True
        if len(sheets) > 1:
            if p.has("cash_short") and any(
                (sh["terms"].get("payment_days") or 999)
                < (neg.threads[plan.supplier_id].standing[1].get("payment_days") or 0)
                for sh in sheets
            ):
                lines.append("If faster payment helps you, one option below pays early.")
            elif any(
                f in plan.policy.trade_first and f in case["negotiable"] for f in ("contract_months", "volume_per_year")
            ):
                lines.append("We are ready to commit for longer if the price reflects it.")
        theirs = neg.threads[plan.supplier_id].standing[1]
        for i, sheet in enumerate(sheets if plan.requests else []):
            if said := self._answered(neg, plan, sheet["terms"], theirs, f"Option {chr(65 + i)}").strip():
                lines.append(said)
                break
        volume = self._volume_proof(neg, plan, sheets)
        if volume:
            lines.append(volume[0])
        lines += ["", "We can award on any of these options:" if len(sheets) > 1 else "Our proposal:"]
        for i, sheet in enumerate(sheets):
            note = trade_note(case, sheets[0]["terms"], sheet["terms"])
            lines.append(f"Option {chr(65 + i)}: {describe(case, sheet['terms'])}{note}")
        lines += ["", SIGNATURE]
        return {
            "subject": case.get("title", "Your quote"),
            "body": "\n".join(lines),
            "term_sheets": sheets,
            "refs": sorted({r for c in claims for r in c.refs} | ({volume[1]} if volume else set())),
        }

    def _volume_proof(self, neg, plan: Plan, sheets: list[dict]) -> tuple[str, str] | None:
        """ "Which volume can you commit to?" (the bots' most common question) - answered once, with the
        forecast we share with suppliers, by ID, so it reads as documentation and not as a claim."""
        if "volume_per_year" not in plan.requests or plan.volume_proved or not self.data:
            return None
        if any(r.startswith("fc:") for r in self.used_refs):
            plan.volume_proved = True  # a duplicate earns nothing ("we have already taken that data into account")
            return None
        parts = neg.case.get("parts") or []
        if len(parts) != 1:
            return None
        num = parts[0].split(":", 1)[-1]
        ids = sorted(k for k in self.data.facts if k.startswith(f"fc:{num}@"))
        if not ids:
            return None
        fc = self.data.facts[ids[-1]]
        change, volume = fc.get("change_pct"), fc.get("volume_per_year")
        if change is None or change < 0:
            return None  # a falling forecast is no argument for a better price
        plan.volume_proved = True
        self.used_refs.add(ids[-1])
        # a commitment we state is one every option keeps (conduct.py: keep our word)
        on_every_option = volume and all(sh["terms"].get("volume_per_year") == volume for sh in sheets)
        commit = f" and we commit to {volume:,} units a year" if on_every_option else ""
        return (
            f"Our demand forecast for this part, shared with you, rose {change:+.1f}% ({ids[-1]}){commit}.",
            ids[-1],
        )

    @staticmethod
    def _answered(neg, plan: Plan, terms: dict, theirs: dict, label: str = "Option A") -> str:
        """One sentence on the requests this offer answers - and on a request the case does not let us meet."""
        words = {
            "index_clause": "the index clause you asked for",
            "contract_months": "the longer commitment you asked for",
            "volume_per_year": "a binding volume",
            "payment_days": "the payment term you proposed",
            "ppm_commitment": "the quality commitment you proposed",
            "chargeback_eur_per_complaint": "the chargeback you proposed",
            "lead_time_days": "your lead time",
            "incoterm": "your delivery terms",
            "effective_date": "your start date",
            "tooling_eur": "your tooling terms",
        }
        met = [
            words[r]
            for r in sorted(plan.requests)
            if r in words and satisfies(neg.case, terms, theirs, r, plan.proposed)
        ]
        return f" {label} includes {' and '.join(met)}." if met else ""

    def keepalive(self, neg: Negotiation, supplier_id: str) -> dict | None:
        """A held thread's clock runs while others negotiate: a harmless question keeps it alive."""
        t = neg.threads[supplier_id]
        if (neg.case.get("round_limit") or 10) - t.rounds_used <= 2:
            return None
        plan = self.tplans[supplier_id]
        asks = [
            "could you confirm your delivery capacity for our annual volume?",
            "could you confirm the lead time you can commit to for the first call-off?",
            "could you confirm the validity of your offer?",
        ]
        question = asks[t.rounds_used % len(asks)]
        return {
            "subject": neg.case.get("title", "Your quote"),
            "body": f"Dear {plan.name} team,\n\nthank you. While we complete our evaluation: {question}\n\n{SIGNATURE}",
        }

    # ------------------------------------------------------------------ closing
    def conclude(self, neg: Negotiation) -> Decision:
        best = None
        rejected = {}
        for sid, t in neg.threads.items():
            if t.closed or t.status in ("walked_away", "no_bid"):
                continue
            for sheet_id, terms in [t.standing]:  # the arena closes on the primary sheet whatever id we send
                if problems := accept_problems(neg, sid, sheet_id):
                    rejected[f"{sid} {sheet_id}"] = problems
                    continue
                c = neg.cost(sid, terms)
                if best is None or c < best[0]:
                    best = (c, sid, sheet_id)
        if best:
            return Decision(
                "accept",
                best[1],
                term_sheet_id=best[2],
                rationale={"c": best[0], "c_alt": neg.c_alt, "rejected": rejected, "why": "cheapest safe sheet"},
            )
        return Decision(
            "walk_away",
            next(iter(neg.threads)),
            rationale={"c_alt": neg.c_alt, "rejected": rejected, "why": "no sheet passes the guards"},
        )


TRADE_WORDS = {
    "payment_days": lambda v: f"payment at {v} days",
    "contract_months": lambda v: f"a {v}-month commitment",
    "volume_per_year": lambda v: f"{v:,} units a year",
    "lead_time_days": lambda v: f"{v} days lead time",
    "incoterm": lambda v: f"delivery {v}",
    "index_clause": lambda v: "an index clause" if v else "a fixed price",
    "ppm_commitment": lambda v: f"{v} ppm",
    "chargeback_eur_per_complaint": lambda v: f"EUR {v} per complaint",
    "effective_date": lambda v: f"a start on {v}",
}


def trade_note(case: dict, lead: dict, terms: dict) -> str:
    """How an option differs from option A, said as the trade it is: "- if you prefer payment at 14 days"."""
    if terms is lead:
        return ""
    diffs = [TRADE_WORDS[f](terms[f]) for f in case["negotiable"] if f in TRADE_WORDS and terms.get(f) != lead.get(f)]
    return f" - our price for {' and '.join(diffs[:2])}" if diffs else ""


PRICE_IN_TEXT = re.compile(
    r"(?:drop|lower|reduce|go(?: down)? to|come down to|can do|offer you)[^.€]{0,50}(?:€|EUR)\s?(\d[\d,]*\.?\d*)", re.I
)


def prices_in_text(body: str) -> list[float]:
    out = []
    for raw in PRICE_IN_TEXT.findall(body or ""):
        try:
            out.append(float(raw.replace(",", "")))
        except ValueError:
            pass
    return out


def parse_breakdown(text: str) -> float | None:
    """Full cost per unit from a cost-breakdown sheet: the EUR elements except margin and totals."""
    skip = ("margin", "profit", "gewinn", "unit price", "price", "total", "sum", "element")
    total, found = 0.0, False
    for line in text.splitlines():
        cells = [c.strip() for c in line.split("|")]
        if len(cells) < 2 or not cells[0] or cells[0].startswith("["):
            continue
        if any(s in cells[0].lower() for s in skip):
            continue
        try:
            value = float(cells[1])
        except ValueError:
            continue
        total += value
        found = True
    return round(total, 2) if found and total > 0 else None


def _k(value: float) -> str:
    return f"{value:,.0f}" if math.isfinite(value) else "inf"
